function maxProduct(s) {
  const n = s.length;
  const radius = new Array(n).fill(0);
  let center = 0;
  let reach = -1;
  for (let i = 0; i < n; i++) {
    let arm = i > reach ? 0 : Math.min(radius[2 * center - i], reach - i);
    while (i - arm - 1 >= 0 && i + arm + 1 < n && s[i - arm - 1] === s[i + arm + 1]) {
      arm++;
    }
    radius[i] = arm;
    if (i + arm > reach) {
      center = i;
      reach = i + arm;
    }
  }
  const prefix = new Array(n).fill(0);
  const suffix = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    const length = 2 * radius[i] + 1;
    prefix[i + radius[i]] = Math.max(prefix[i + radius[i]], length);
    suffix[i - radius[i]] = Math.max(suffix[i - radius[i]], length);
  }
  for (let i = n - 2; i >= 0; i--) {
    prefix[i] = Math.max(prefix[i], prefix[i + 1] - 2);
  }
  for (let i = 1; i < n; i++) {
    prefix[i] = Math.max(prefix[i], prefix[i - 1]);
  }
  for (let i = 1; i < n; i++) {
    suffix[i] = Math.max(suffix[i], suffix[i - 1] - 2);
  }
  for (let i = n - 2; i >= 0; i--) {
    suffix[i] = Math.max(suffix[i], suffix[i + 1]);
  }
  let best = 0;
  for (let i = 0; i < n - 1; i++) {
    best = Math.max(best, prefix[i] * suffix[i + 1]);
  }
  return best;
}

