function maxProduct(s) {
  const isPalindrome = (a, b) => {
    for (; a < b; a++, b--) if (s[a] !== s[b]) return false;
    return true;
  };
  const found = [];
  for (let i = 0; i < s.length; i++)
    for (let j = i; j < s.length; j += 2)
      if (isPalindrome(i, j)) found.push([i, j]);
  let best = 0;
  for (const [i, j] of found)
    for (const [k, l] of found)
      if (j < k) best = Math.max(best, (j - i + 1) * (l - k + 1));
  return best;
}

