function generate(rand, size) {
  const pick = (letters) => letters[Math.floor(rand() * letters.length)];
  const randomText = (length, letters) => Array.from({ length }, () => pick(letters)).join('');
  const mirrored = (half, letters) => {
    const left = randomText(half, letters);
    return left + pick(letters) + [...left].reverse().join('');
  };
  if (size === 'small') {
    const length = 2 + Math.floor(rand() * 11);
    const letters = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
    if (rand() < 0.4) {
      let text = '';
      while (text.length < length) text += mirrored(Math.floor(rand() * 3), letters);
      return [text.slice(0, length)];
    }
    return [randomText(length, letters)];
  }
  const length = 8000 + Math.floor(rand() * 2001);
  const mode = Math.floor(rand() * 4);
  if (mode === 0) return ['a'.repeat(length)];
  if (mode === 1) return [randomText(length, 'ab')];
  if (mode === 2) return [randomText(length, 'abcdefghijklmnopqrstuvwxyz')];
  let text = '';
  while (text.length < length) text += mirrored(Math.floor(rand() * 800), 'abc') + pick('xyz');
  return [text.slice(0, length)];
}
